function updatePlayer() {
  const p = player;
  if (p.dead) { p.deadT++; p.vy += 0.35; p.y += p.vy; return; }

  if (p.shotCd > 0) p.shotCd--;
  if (p.star > 0) p.star--;
  if (p.invuln > 0) p.invuln--;

  const ax = axisX();
  const ACC = 0.04, FR = 0.32;
  const runKey = keys["b"] || keys["B"] || keys["Shift"];
  const walk = { small: 1.4, big: 1.5, super: 1.6 };
  const run  = { small: 1.9, big: 2.0, super: 2.2 };
  const yoshiWalk = 1.7, yoshiRun = 2.5;
  const MAX = p.yoshi ? (runKey ? yoshiRun : yoshiWalk) : (runKey ? run[p.power] : walk[p.power]);
  if (ax) {
    p.vx += ax * ACC;
    p.vx = Math.max(-MAX, Math.min(MAX, p.vx));
    p.facing = ax;
    if (p.onGround) p.animT += 1;
  } else {
    p.vx -= Math.sign(p.vx) * (p.onGround ? FR : FR * 0.25);
    if (Math.abs(p.vx) < FR) p.vx = 0;
  }
  if (Math.abs(p.vx) < 0.02 && !ax) p.anim = "idle";

  // --- jumping / propeller / yoshi flutter ---
  const jHeld = jumpHeld(), jPress = jumpPressed();
  const wantJump = (jPress && p.onGround) || (jHeld && p.yoshi && p.onGround && p.vy > -1);
  if (wantJump) {
    const base = p.big ? -7.9 : -7.6;
    p.vy = p.yoshi ? -4.9 : base;
    p.onGround = false;
    if (!p.yoshi) SFX.jump();
  }
  if (p.power === "prop" && !p.onGround) {
    if (jHeld) { p.vy += -0.62 * 1; if (p.vy < -3.6) p.vy = -3.6; }
    else { p.vy += 0.5; if (p.vy > 5.5) p.vy = 5.5; }
  } else {
    if (p.vy < -1.5 && !jHeld && !p.yoshi && p.power !== "prop") p.vy += 0.22;  // variable jump
    p.vy += p.yoshi && !jHeld ? 0.36 : 0.38;
    if (p.vy > 8.5) p.vy = 8.5;
  }
  if (p.yoshi && !p.onGround && jHeld && p.vy > 0.2) p.vy = Math.min(p.vy, 1.9);  // flutter

  p.x += p.vx;
  if (p.x < 0) { p.x = 0; p.vx = 0; }
  if (p.x > LW * 16 - p.w) { p.x = LW * 16 - p.w; p.vx = 0; }

  const prevBottom = p.y + p.h;
  moveAndCollide(p);

  // pass-through (one-way) platforms
  if (p.vy >= 0) {
    const bottom = p.y + p.h;
    const r0 = Math.floor(bottom / 16);
    const c1 = tileAt(Math.floor((p.x + 1) / 16), r0), c2 = tileAt(Math.floor((p.x + p.w - 1) / 16), r0);
    if ((c1 === "p" || c2 === "p") && bottom >= r0 * 16 && prevBottom <= r0 * 16 + 2) {
      p.y = r0 * 16 - p.h - 0.01; p.vy = 0; p.onGround = true;
    }
  }

  // crystal lift riding
  if (p.ride) {
    const L = p.ride;
    if (Math.abs(p.x + p.w / 2 - L.x) > L.w / 2 + 10) p.ride = null;
  }
