let last = performance.now();
let acc = 0;
const STEP = 1000 / 60;
function frame(now) {
  let delta = now - last;
  last = now;
  if (delta > 100) delta = 100; // clamp after tab switch
  acc += delta;
  while (acc >= STEP) {
    update(1); // dt in "frames"
    acc -= STEP;
  }
  draw();
  requestAnimationFrame(frame);
}

function moveAndCollide(e) {
  e.onGround = false;
  const prevRightX = e.x + e.w;
  const prevLeftX = e.x;
  e.x += e.vx;
  if (hitSolid(e)) {
    const x0 = Math.floor(e.x / 16), x1 = Math.floor((e.x + e.w) / 16);
    const y0 = Math.floor(e.y / 16), y1 = Math.floor((e.y + e.h) / 16);
    let hitX = false;
    if (e.vx > 0) {
      for (let tx = x0; tx <= x1 && !hitX; tx++)
        for (let ty = y0; ty <= y1; ty++)
          if (isSolid(tileAt(tx, ty)) && tx * 16 >= prevRightX) {
            e.x = tx * 16 - e.w - 0.01; hitX = true; break;
          }
    } else if (e.vx < 0) {
      for (let tx = x1; tx >= x0 && !hitX; tx--)
        for (let ty = y0; ty <= y1; ty++)
          if (isSolid(tileAt(tx, ty)) && (tx + 1) * 16 <= prevLeftX + 4) {
            e.x = (tx + 1) * 16 + 0.01; hitX = true; break;
          }
    }
    if (hitX) {
      e.vx = -e.vx * (e.noBounce ? 0 : 1);
      if (e.noBounce) e.vx = 0;
    }
  }
  const prevBottomV = e.y + e.h;
  const prevTopV = e.y;
  e.y += e.vy;
  if (hitSolid(e)) {
    const x0 = Math.floor(e.x / 16), x1 = Math.floor((e.x + e.w) / 16);
    const y0 = Math.floor(e.y / 16), y1 = Math.floor((e.y + e.h) / 16);
    let hitHead = false;
    for (let ty = y0; ty <= y1; ty++) for (let tx = x0; tx <= x1; tx++) {
      if (!isSolid(tileAt(tx, ty))) continue;
      if (e.vy > 0 && prevBottomV <= ty * 16 + 4) {
        e.y = ty * 16 - e.h - 0.01; e.vy = 0; e.onGround = true;
      } else if (e.vy < 0 && prevTopV >= (ty + 1) * 16 - 4) {
        e.y = (ty + 1) * 16 + 0.01; e.vy = 0.01; hitHead = true;
      }
    }
    if (hitHead && e.onHead) e.onHead(e);
  }
  return e;
}
